package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	rawCh := make(chan string)
	resultCh := make(chan string)

	go readLines("input.log", rawCh)

	for i := 0; i < 5; i++ {
		go processor(rawCh, resultCh)
	}

	go writeResults("output.log", resultCh)

	select {}
}

func readLines(filename string, ch chan<- string) {
	file, err := os.Open(filename)
	if err != nil {
		panic(err)
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		ch <- scanner.Text()
	}
}

func processor(in <-chan string, out chan<- string) {
	for line := range in {
		processed := strings.ToUpper(line)
		out <- processed
	}
}

func writeResults(filename string, ch <-chan string) {
	file, err := os.Create(filename)
	if err != nil {
		panic(err)
	}
	defer file.Close()
	for line := range ch {
		fmt.Fprintln(file, line)
	}
}

The issue is that the channels are unbuffered, which causes the reader goroutine to block when no processor is ready, and the processor to block when the writer is not ready. Under high load, the writer becomes a bottleneck because it writes to disk synchronously, causing backpressure that eventually drops messages when the reader's goroutine is blocked and the main program exits (since main does `select {}` without waiting). Actually, the code as shown should not drop messages, it would just slow down. But if there is an error during writing, it could panic. More likely, the issue is that the `select {}` in main does not wait for the goroutines to finish, so if any goroutine panics or the input file ends, the program exits and messages in the channels are lost. To fix, we should use buffered channels and add proper synchronization (e.g., WaitGroup). Also, ensure the writer can keep up by using buffered I/O. Proposed fix:

```go
rawCh := make(chan string, 1000)
resultCh := make(chan string, 1000)

var wg sync.WaitGroup
wg.Add(5)
for i := 0; i < 5; i++ {
	go func() {
		defer wg.Done()
		processor(rawCh, resultCh)
	}()
}

go func() {
	wg.Wait()
	close(resultCh)
}()

go readLines("input.log", rawCh)
writeResults("output.log", resultCh)
```

This ensures the writer drains resultCh before exiting, and buffering reduces blocking. Also, use bufio.Writer in writeResults.

