{"path": "src/parser/evaluate.ts", "content": "import type { Node } from './ast';

/**
 * Evaluates an AST node to a number.
 * @param node - The AST node to evaluate.
 * @param variables - A map of variable names to their numeric values.
 * @returns The numeric result of the evaluation.
 * @throws {Error} If division by zero occurs or an unknown variable is referenced.
 */
export function evaluate(node: Node, variables: Map<string, number>): number {
  switch (node.type) {
    case 'number':
      return node.value;
    case 'binary': {
      const left = evaluate(node.left, variables);
      const right = evaluate(node.right, variables);
      switch (node.operator) {
        case '+': return left + right;
        case '-': return left - right;
        case '*': return left * right;
        case '/': {
          if (right === 0) {
            throw new Error('Division by zero');
          }
          return left / right;
        }
        default:
          // Exhaustive check for binary operators
          const _exhaustiveBinary: never = node.operator;
          return _exhaustiveBinary;
      }
    }
    case 'unary': {
      const operand = evaluate(node.operand, variables);
      switch (node.operator) {
        case '-': return -operand;
        case '!': return operand === 0 ? 1 : 0;
        default:
          // Exhaustive check for unary operators
          const _exhaustiveUnary: never = node.operator;
          return _exhaustiveUnary;
      }
    }
    case 'variable': {
      const value = variables.get(node.name);
      if (value === undefined) {
        throw new Error(`Undefined variable: ${node.name}`);
      }
      return value;
    }
    default:
      // Exhaustive check for node types
      const _exhaustiveNode: never = node;
      return _exhaustiveNode;
  }
}
"}

