  const { customerId, items, notes } = req.body;
  if (typeof customerId !== 'string' || customerId.trim() === '') {
    return res.status(400).json({ error: 'customerId must be a non-empty string' });
  }
  if (!Array.isArray(items) || items.length === 0) {
    return res.status(400).json({ error: 'items must be a non-empty array' });
  }
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (typeof item !== 'object' || item === null || typeof item.itemId !== 'string' || item.itemId.trim() === '') {
      return res.status(400).json({ error: 'each item must have a non-empty itemId string' });
    }
    if (!Number.isInteger(item.quantity) || item.quantity <= 0) {
      return res.status(400).json({ error: 'each item quantity must be a positive integer' });
    }
  }
  if (notes !== undefined && typeof notes !== 'string') {
    return res.status(400).json({ error: 'notes must be a string if provided' });
  }
  const order = { id: orderCounter++, customerId, items, notes: notes || '' };
